class BankException extends Exception {
    public BankException(String msg) { super(msg); }
}

// 1. 定义自定义异常
class NoMoneyException extends BankException {
    public NoMoneyException(int lack) {
        // 调用父类构造函数
        super("余额不足: " + lack);
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            withdraw(1000);
        } catch (NoMoneyException e) {
            System.out.println(e.getMessage());
        } catch (BankException e) {
            System.out.println("银行错误");
        }
    }

    static void withdraw(int money) throws BankException {
        int balance = 500;
        if (money > balance) {
            // 2. 抛出异常
            throw new NoMoneyException(money - balance);
        }
    }
}
